    void filterByNameDoesNotMatchUnrelated() {
        Customer ada = new Customer(1, "Ada", "Aaltonen", "test@example.com", "Finland", CustomerStatus.ACTIVE);
        CustomerFilter filter = new CustomerFilter("bruno", null);
        assertFalse(filter.matches(ada));
    }

    @Test
    void multipleNameTermsMustAllMatch() {
        Customer ada = new Customer(1, "Ada", "Aaltonen", "test@example.com", "Finland", CustomerStatus.ACTIVE);
