+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+
+public record CustomerFilter(String nameFilter, List<CustomerStatus> statusFilter) {
+
+    public boolean matches(Customer customer) {
+        if (!matchesName(customer)) {
+            return false;
+        }
+        if (!matchesStatus(customer)) {
+            return false;
+        }
+        return true;
+    }
+
+    private boolean matchesName(Customer customer) {
+        if (nameFilter == null || nameFilter.isBlank()) {
+            return true;
+        }
+        String[] terms = nameFilter.trim().split("\\s+");
+        String firstName = normalizeForMatching(customer.firstName());
+        String lastName = normalizeForMatching(customer.lastName());
+        for (String term : terms) {
+            String normalizedTerm = normalizeForMatching(term);
+            if (!firstName.contains(normalizedTerm) && !lastName.contains(normalizedTerm)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private boolean matchesStatus(Customer customer) {
+        if (statusFilter == null || statusFilter.isEmpty()) {
+            return true;
+        }
+        return statusFilter.contains(customer.status());
+    }
+
+    private static String normalizeForMatching(String text) {
+        if (text == null) {
+            return "";
+        }
+        String normalized = Normalizer.normalize(text, Normalizer.Form.NFD);
+        normalized = normalized.replaceAll("\\p{M}", "");
+        return normalized.toLowerCase();
+    }
+}
