+class CustomerFilterTest {
+
+    @Test
+    void filterByNameMatchesSubstring() {
+        Customer ada = new Customer(1, "Ada", "Aaltonen", "test@example.com", "Finland", CustomerStatus.ACTIVE);
+        CustomerFilter filter = new CustomerFilter("aalto", null);
+        assertTrue(filter.matches(ada));
+    }
+
+    @Test
+    void filterByNameIsCaseInsensitive() {
+        Customer ada = new Customer(1, "Ada", "Aaltonen", "test@example.com", "Finland", CustomerStatus.ACTIVE);
+        CustomerFilter filter = new CustomerFilter("AALTONEN", null);
+        assertTrue(filter.matches(ada));
+    }
+
+    @Test
+    void filterByNameIsAccentInsensitive() {
+        Customer jarno = new Customer(1, "Jarno", "Mäkinen", "test@example.com", "Finland", CustomerStatus.ACTIVE);
+        CustomerFilter filter = new CustomerFilter("makinen", null);
+        assertTrue(filter.matches(jarno));
+    }
+
+    @Test
+    void filterByNameDoesNotMatchUnrelated() {
+        Customer ada = new Customer(1, "Ada", "Aaltonen", "test@example.com", "Finland", CustomerStatus.ACTIVE);
+        CustomerFilter filter = new CustomerFilter("bruno", null);
+        assertFalse(filter.matches(ada));
+    }
+
+    @Test
+    void multipleNameTermsMustAllMatch() {
+        Customer ada = new Customer(1, "Ada", "Aaltonen", "test@example.com", "Finland", CustomerStatus.ACTIVE);
+        CustomerFilter filter = new CustomerFilter("ada aalto", null);
+        assertTrue(filter.matches(ada));
+
+        CustomerFilter filterReversed = new CustomerFilter("aalto ada", null);
+        assertTrue(filterReversed.matches(ada));
+    }
+
+    @Test
+    void multipleNameTermsFailIfOneDoesNotMatch() {
+        Customer ada = new Customer(1, "Ada", "Aaltonen", "test@example.com", "Finland", CustomerStatus.ACTIVE);
+        CustomerFilter filter = new CustomerFilter("ada bruno", null);
+        assertFalse(filter.matches(ada));
+    }
+
+    @Test
+    void emptyNameFilterMatchesAll() {
+        Customer ada = new Customer(1, "Ada", "Aaltonen", "test@example.com", "Finland", CustomerStatus.ACTIVE);
+        CustomerFilter filter = new CustomerFilter(null, null);
+        assertTrue(filter.matches(ada));
+
+        CustomerFilter filter2 = new CustomerFilter("", null);
+        assertTrue(filter2.matches(ada));
+    }
+
+    @Test
+    void statusFilterMatchesSelected() {
+        Customer ada = new Customer(1, "Ada", "Aaltonen", "test@example.com", "Finland", CustomerStatus.ACTIVE);
+        CustomerFilter filter = new CustomerFilter(null, java.util.List.of(CustomerStatus.ACTIVE));
+        assertTrue(filter.matches(ada));
+    }
+
+    @Test
+    void statusFilterRejectsUnselected() {
+        Customer ada = new Customer(1, "Ada", "Aaltonen", "test@example.com", "Finland", CustomerStatus.ACTIVE);
+        CustomerFilter filter = new CustomerFilter(null, java.util.List.of(CustomerStatus.CLOSED));
+        assertFalse(filter.matches(ada));
+    }
+
+    @Test
+    void emptyStatusFilterMatchesAll() {
+        Customer ada = new Customer(1, "Ada", "Aaltonen", "test@example.com", "Finland", CustomerStatus.ACTIVE);
+        CustomerFilter filter = new CustomerFilter(null, java.util.List.of());
+        assertTrue(filter.matches(ada));
+    }
+}
